begin;

-- Garde-fou : on refuse d'importer si les tables contiennent déjà des données
-- (pour ne jamais créer de doublons). Supprimez ce bloc seulement si vous savez ce que vous faites.
do $$
begin
    if exists (select 1 from banque_mouvements) or exists (select 1 from caisse_mouvements)
       or exists (select 1 from cheques) or exists (select 1 from remises_cheques) or exists (select 1 from factures) then
        raise exception 'Import annulé : banque_mouvements / caisse_mouvements / cheques / remises_cheques / factures contiennent déjà des lignes.';
    end if;
end $$;

