-- ---------- Factures ----------





-- ---------- Rattachement des fournisseurs (fournisseur_id) ----------
update banque_mouvements t set fournisseur_id = f.id from fournisseurs f where f.nom = t.fournisseur and t.fournisseur_id is null;
update caisse_mouvements t set fournisseur_id = f.id from fournisseurs f where f.nom = t.fournisseur and t.fournisseur_id is null;
update cheques t set fournisseur_id = f.id from fournisseurs f where f.nom = t.fournisseur and t.fournisseur_id is null;
update factures t set fournisseur_id = f.id from fournisseurs f where f.nom = t.fournisseur and t.fournisseur_id is null;

-- ---------- CONTRÔLES (comparer avec le tableau du mode opératoire) ----------
select 'banque_mouvements' as table_, count(*) as lignes, coalesce(sum(credit),0) as total_credit, coalesce(sum(debit),0) as total_debit from banque_mouvements
union all select 'caisse_mouvements', count(*), coalesce(sum(credit),0), coalesce(sum(debit),0) from caisse_mouvements
union all select 'cheques', count(*), 0, coalesce(sum(montant),0) from cheques
union all select 'remises_cheques', count(*), coalesce(sum(montant_total),0), 0 from remises_cheques
union all select 'remise_cheques_details', count(*), coalesce(sum(montant),0), 0 from remise_cheques_details
union all select 'factures', count(*), 0, coalesce(sum(montant_ttc),0) from factures;

commit;
